// Books: the EPUB books on the frame's card, read on the frame. The library
// lists every .epub below the scene's folder (the whole card by default), the
// book you read last first; a book opens where you left it.
//
// An EPUB is a ZIP of XHTML chapters. frameos.readAsset reads one member of it
// ({ entry }) inflated by the runtime, as text, so a chapter costs its own
// size and never the book's. The chapter's text becomes blocks (paragraphs,
// headings, list items, quotes), and the blocks become pages here: each line
// is measured with the advance widths of the frame's face (Ubuntu), so the
// page holds exactly what fits, at any text size, in one column or two on a
// wide screen. A book's pictures (and its cover in the library) are decoded
// from the ZIP at the size they are drawn, over the page's colour where they
// are transparent; their size for the layout is read off their headers.
//
// Where you are is the private `spot` field, kept on disk: the book, its
// chapter, the paragraph and the character the page starts at, and the starts
// of the pages read so far in the chapter, so a page back is never laid out
// again, even on a frame that sleeps between pages. A book handed over by
// another scene (the Files app, through `settings.opens`) comes in the public
// field `file`, "<storage>:<path>", and opens where it was left.
//
// Taps: the left third of a page goes back, the rest forward; swipes and the
// keys turn pages too (UP / LEFT back, DOWN / RIGHT forward, any other key
// back to the library; held keys stay the frame's).

const SIZES = [18, 20, 22, 24, 26, 29, 32, 36, 40]
const DEFAULT_SIZE = 4
const LIST_MS = 5 * 60 * 1000
const BOOKS_KEPT = 40

// Advance widths of U+0020..U+017F in hundredths of an em, two digits each:
// Ubuntu Regular, the face every frame draws text in (00 = no glyph).
const WIDTHS = ''
const PUNCT = { 0x2013: 50, 0x2014: 100, 0x2015: 100, 0x2018: 24, 0x2019: 24, 0x201a: 24, 0x201c: 42, 0x201d: 42, 0x201e: 42, 0x2020: 48, 0x2021: 48, 0x2022: 36, 0x2026: 100, 0x2042: 100 }
const advance = []
for (let i = 0; i < 352; i++) advance.push(parseInt(WIDTHS.slice(i * 2, i * 2 + 2), 10) || 0)

function widthOf(code) {
  if (code >= 32 && code < 384) return advance[code - 32] || 58
  const p = PUNCT[code]
  if (p) return p
  if (code >= 0x2e80) return 100 // CJK and the like: an em
  return 58
}

// How each kind of block is set: size against the body text, bold, the room
// above and below in lines, the left inset in ems.
const STYLES = {
  h: { scale: 1.35, bold: true, before: 1, after: 0.5, left: 0 },
  h3: { scale: 1.12, bold: true, before: 0.8, after: 0.3, left: 0 },
  p: { scale: 1, bold: false, before: 0, after: 0, left: 0 },
  li: { scale: 1, bold: false, before: 0.15, after: 0.15, left: 1 },
  q: { scale: 1, bold: false, before: 0.3, after: 0.3, left: 1.5 },
  hr: { scale: 1, bold: false, before: 0.3, after: 0.3, left: 0 },
}

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`
const raw = (n) => `${Math.round(n)}px`

// What lives only as long as the interpreter: the book open, the chapter
// parsed, the library listed.
let opened = null // { path, title, author, spine, toc }
let loaded = { key: '', blocks: [], more: false, chars: 0 }
let listed = { folder: null, at: 0, books: [] }
const metas = new Map() // path -> { title, author } | { error }

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)
const baseName = (path) => path.split('/').pop()

// A book is "<storage>:<path>": which of app.frame.storages it is in (the TF
// card's "assets", "internal") and its path there. A key from before storages
// (a bare path) was in the assets folder, which on an ESP32 with no card is
// its internal storage: normalKey says which, by the storages listed.
const STORAGE_IDS = ['assets', 'internal']
function placeOf(key) {
  const at = key.indexOf(':')
  const storage = at > 0 ? key.slice(0, at) : ''
  return STORAGE_IDS.includes(storage) ? { storage, path: key.slice(at + 1) } : { storage: 'assets', path: key }
}
const keyOf = (storage, path) => `${storage}:${path}`
function normalKey(key, storages) {
  if (typeof key !== 'string' || !key) return key
  const at = key.indexOf(':')
  if (at > 0 && STORAGE_IDS.includes(key.slice(0, at))) return key
  const home = storages.some((s) => s.id === 'assets') ? 'assets' : storages[0].id
  return keyOf(home, key)
}
const bookName = (key) => baseName(placeOf(key).path).replace(/\.epub$/i, '').replace(/[_]+/g, ' ')

// Where the asset calls reach (FrameOS 2026.11.11+), and before that the one
// assets folder.
function storagesOf(app) {
  const storages = Array.isArray(app.frame.storages) ? app.frame.storages.filter((s) => s && STORAGE_IDS.includes(s.id)) : []
  return storages.length > 0 ? storages : [{ id: 'assets', name: 'Internal storage' }]
}

// ---- Text out of XHTML -------------------------------------------------------

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0', mdash: '\u2014', ndash: '\u2013',
  hellip: '\u2026', lsquo: '\u2018', rsquo: '\u2019', ldquo: '\u201c', rdquo: '\u201d', laquo: '\u00ab',
  raquo: '\u00bb', copy: '\u00a9', reg: '\u00ae', trade: '\u2122', shy: '', thinsp: ' ', ensp: ' ', emsp: ' ',
  bull: '\u2022', middot: '\u00b7', eacute: '\u00e9', egrave: '\u00e8', aacute: '\u00e1', agrave: '\u00e0',
  ouml: '\u00f6', uuml: '\u00fc', auml: '\u00e4', szlig: '\u00df', ccedil: '\u00e7', iacute: '\u00ed',
  oacute: '\u00f3', uacute: '\u00fa', ntilde: '\u00f1', deg: '\u00b0', times: '\u00d7', frac12: '\u00bd',
}

function decode(text) {
  return text.replace(/&(#[xX][0-9a-fA-F]+|#\d+|[a-zA-Z]+\d*);/g, (all, name) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : ''
    }
    const named = ENTITIES[name]
    return named === undefined ? all : named
  })
}

const clean = (text) =>
  decode(text.replace(/<[^>]*>/g, ''))
    .replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/[ \t\r\n\f]+/g, ' ')
    .trim()

// An SVG in the book's XHTML and the image element in it. The patterns are
// built from their names: the scene linter reads those tags written out in an
// app's source as an SVG the app draws, which these are not.
const SVG_NAME = 'svg'
const IMAGE_NAME = 'image'
const SVG_BLOCK = new RegExp(`<${SVG_NAME}\\b[\\s\\S]*?</${SVG_NAME}\\s*>`, 'gi')
const SVG_IMAGE = new RegExp(`<${IMAGE_NAME}\\b[^>]*>`, 'i')

// The pictures the frame decodes (no SVG: a book's are its covers, made <img> above).
const PICTURES = /\.(jpe?g|png|gif|webp|bmp)$/i

const BLOCK_TAGS = new Set([
  'p', 'div', 'section', 'article', 'header', 'footer', 'aside', 'main', 'nav', 'figure', 'figcaption',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'ul', 'ol', 'dl', 'dt', 'dd', 'blockquote', 'pre', 'table',
  'tr', 'td', 'th', 'caption', 'body', 'center', 'address', 'hgroup',
])

// A chapter's text as blocks: { k: kind, t: text, ni: no first-line indent },
// and its pictures as { k: 'img', src: the member's path, alt }. base is the
// chapter's folder in the book, which a picture's src is relative to.
function parseChapter(xhtml, base) {
  let s = xhtml
  const body = s.search(/<body[\s>]/i)
  if (body >= 0) s = s.slice(body)
  s = s
    .replace(/<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<![^>]*>/g, ' ')
    // A picture drawn as an SVG image element (many covers) is a picture
    // like <img>.
    .replace(SVG_BLOCK, (svg) => {
      const image = SVG_IMAGE.exec(svg)
      const href = image && (attrOf(image[0], 'xlink:href') || attrOf(image[0], 'href'))
      return href ? `<img src="${href.replace(/"/g, '&quot;')}"/>` : ' '
    })
    .replace(/<(script|style|head)\b[\s\S]*?<\/\1\s*>/gi, ' ')
  const blocks = []
  let text = ''
  let kind = 'p'
  let quotes = 0
  let heads = 0 // inside an <hgroup>: its <p> (a chapter's title under its number) is a heading
  let broke = false
  const lists = [] // the open lists: 0 for a bulleted one, else the next number
  let marker = '' // a list item's bullet or number, waiting for its text
  const flush = () => {
    const t = text.includes('&') ? decode(text) : text
    let tidy = t.replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '').replace(/[ \t\r\n\f]+/g, ' ').trim()
    text = ''
    if (/^(\u2022|\d+\.)$/.test(tidy)) {
      // An item whose text is in a block of its own (<li><p>…</p></li>).
      marker = tidy + ' '
      return
    }
    let k = kind
    if (tidy && marker) {
      tidy = marker + tidy
      marker = ''
      k = 'li'
    }
    if (tidy) blocks.push(broke ? { k, t: tidy, ni: true } : { k, t: tidy })
    broke = false
  }
  const re = /<(\/?)([a-zA-Z][\w:.-]*)([^>]*?)(\/?)>|([^<]+)|</g
  let m
  while ((m = re.exec(s))) {
    if (m[5] !== undefined) {
      text += m[5]
      continue
    }
    if (m[2] === undefined) {
      text += '<'
      continue
    }
    const tag = m[2].toLowerCase()
    const closing = m[1] === '/'
    if (tag === 'br') {
      const k = kind
      flush()
      kind = k
      broke = true
      continue
    }
    if (tag === 'hr') {
      flush()
      blocks.push({ k: 'hr', t: '' })
      continue
    }
    if (tag === 'img' && !closing) {
      const src = attrOf(' ' + m[3], 'src')
      if (src && PICTURES.test(src.split(/[?#]/)[0])) {
        const k = kind
        flush()
        kind = k
        blocks.push({ k: 'img', t: '', src: resolve(base || '', src), alt: clean(attrOf(' ' + m[3], 'alt') || '') })
      }
      continue
    }
    if (!BLOCK_TAGS.has(tag)) {
      // Inline: a space where a word ends at the tag is the text's own.
      continue
    }
    flush()
    if (tag === 'blockquote') quotes = Math.max(0, quotes + (closing ? -1 : 1))
    if (tag === 'hgroup') heads = Math.max(0, heads + (closing ? -1 : 1))
    if (tag === 'ul' || tag === 'ol') {
      if (closing) lists.pop()
      else if (m[4] !== '/') lists.push(tag === 'ol' ? 1 : 0)
    }
    const plain = quotes > 0 ? 'q' : 'p'
    if (closing || m[4] === '/') kind = plain
    else if (tag === 'h1' || tag === 'h2') kind = 'h'
    else if (tag === 'h3' || tag === 'h4' || tag === 'h5' || tag === 'h6') kind = 'h3'
    else if (tag === 'li') {
      kind = 'li'
      const n = lists.length > 0 ? lists[lists.length - 1] : 0
      text = n > 0 ? `${n}. ` : '\u2022 '
      if (n > 0) lists[lists.length - 1] = n + 1
    } else if (tag === 'dd') kind = 'li'
    else kind = heads > 0 && tag === 'p' ? 'h3' : plain
  }
  flush()
  return blocks
}

// ---- The book: container, package, contents ---------------------------------

function attrOf(tag, name) {
  const m = new RegExp('\\s' + name.replace(/[:]/g, '\\:') + '\\s*=\\s*("([^"]*)"|\'([^\']*)\')', 'i').exec(tag)
  return m ? decode(m[2] !== undefined ? m[2] : m[3]) : null
}

const dirOf = (path) => (path.includes('/') ? path.slice(0, path.lastIndexOf('/') + 1) : '')

function resolve(base, href) {
  let path = href.split('#')[0]
  try {
    path = decodeURIComponent(path)
  } catch (e) {}
  const parts = (path.startsWith('/') ? path.slice(1) : base + path).split('/')
  const out = []
  for (const part of parts) {
    if (part === '..') out.pop()
    else if (part !== '.' && part !== '') out.push(part)
  }
  return out.join('/')
}

function readEntry(key, entry, offset, length) {
  const at = placeOf(key)
  return frameos.readAsset(at.path, { entry, text: true, offset: offset || 0, length: length || 1024 * 1024, storage: at.storage })
}

// The package: where the chapters are, in order, and what the book is called.
function readPackage(path) {
  const container = readEntry(path, 'META-INF/container.xml')
  if (!container) return { error: 'This is not an EPUB book.' }
  const rootfile = /<rootfile\b[^>]*>/i.exec(container)
  const opfPath = rootfile && attrOf(rootfile[0], 'full-path')
  const opf = opfPath ? readEntry(path, opfPath) : null
  if (!opf) return { error: 'The book has no table of its chapters.' }
  const base = dirOf(opfPath)
  const items = {}
  let nav = null
  let ncx = null
  let cover = null
  for (const m of opf.match(/<(?:\w+:)?item\b[^>]*>/gi) || []) {
    const id = attrOf(m, 'id')
    const href = attrOf(m, 'href')
    if (!id || !href) continue
    const type = attrOf(m, 'media-type') || ''
    const item = { href: resolve(base, href), type }
    items[id] = item
    const props = attrOf(m, 'properties') || ''
    if (/(^|\s)nav(\s|$)/.test(props)) nav = item.href
    if (/(^|\s)cover-image(\s|$)/.test(props)) cover = item.href
    if (type === 'application/x-dtbncx+xml') ncx = ncx || item.href
  }
  const spine = []
  const spineTag = /<(?:\w+:)?spine\b[^>]*>/i.exec(opf)
  const tocId = spineTag && attrOf(spineTag[0], 'toc')
  if (tocId && items[tocId]) ncx = items[tocId].href
  for (const m of opf.match(/<(?:\w+:)?itemref\b[^>]*>/gi) || []) {
    const item = items[attrOf(m, 'idref')]
    if (!item || attrOf(m, 'linear') === 'no') continue
    if (item.type && !/html|xml/.test(item.type)) continue
    spine.push(item.href)
  }
  if (spine.length === 0) return { error: 'The book has no chapters.' }
  const meta = (tag) => {
    const m = new RegExp('<(?:dc:)?' + tag + '\\b[^>]*>([\\s\\S]*?)</(?:dc:)?' + tag + '>', 'i').exec(opf)
    return m ? clean(m[1]) : ''
  }
  // An EPUB 2 names its cover in <meta name="cover" content="the item's id">.
  if (!cover) {
    const named = /<meta\b[^>]*\bname\s*=\s*["']cover["'][^>]*>/i.exec(opf)
    const item = named && items[attrOf(named[0], 'content')]
    if (item && PICTURES.test(item.href)) cover = item.href
  }
  return { title: meta('title') || bookName(path), author: meta('creator'), spine, nav, ncx, cover }
}

// The contents, as { label, s } with s the chapter in the spine it opens.
function readContents(path, pkg) {
  const toc = []
  const place = (file, href, label) => {
    const target = resolve(dirOf(file), href)
    const s = pkg.spine.indexOf(target)
    if (s >= 0 && label && !toc.some((entry) => entry.s === s)) toc.push({ label, s })
  }
  if (pkg.nav) {
    const doc = readEntry(path, pkg.nav)
    if (doc) {
      const start = doc.search(/<nav\b[^>]*epub:type\s*=\s*["'][^"']*\btoc\b/i)
      const from = start >= 0 ? start : doc.search(/<nav\b/i)
      const part = from >= 0 ? doc.slice(from, doc.indexOf('</nav>', from) + 6 || undefined) : doc
      const re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi
      let m
      while ((m = re.exec(part))) {
        const href = attrOf(m[1] ? ' ' + m[1] : '', 'href')
        if (href) place(pkg.nav, href, clean(m[2]))
      }
    }
  }
  if (toc.length === 0 && pkg.ncx) {
    const doc = readEntry(path, pkg.ncx)
    if (doc) {
      const re = /<navPoint\b[\s\S]*?<text>([\s\S]*?)<\/text>[\s\S]*?<content\b([^>]*)>/gi
      let m
      while ((m = re.exec(doc))) {
        const href = attrOf(' ' + m[2], 'src')
        if (href) place(pkg.ncx, href, clean(m[1]))
      }
    }
  }
  toc.sort((a, b) => a.s - b.s)
  return toc
}

function openBook(path) {
  if (opened && opened.path === path) return opened
  const kept = frameos.recall('book')
  if (kept && typeof kept === 'object' && kept.path === path && Array.isArray(kept.spine)) {
    opened = kept
    return opened
  }
  const pkg = readPackage(path)
  if (pkg.error) return { path, error: pkg.error }
  opened = { path, title: pkg.title, author: pkg.author, cover: pkg.cover, spine: pkg.spine, toc: readContents(path, pkg) }
  frameos.remember('book', opened)
  metas.set(path, { title: pkg.title, author: pkg.author, cover: pkg.cover })
  return opened
}

// ---- Chapters, in parts the frame can hold -----------------------------------

// A part of a chapter is this many bytes of its XHTML: a chapter longer than
// that (a whole book in one file) is read a part at a time.
const partBytes = (ui) => (ui.embedded ? 256 * 1024 : 2 * 1024 * 1024)

function utf8Length(text) {
  try {
    return unescape(encodeURIComponent(text)).length
  } catch (e) {
    return text.length * 3
  }
}

function chapterOf(book, s, p, ui) {
  const key = `${book.path}|${s}|${p}`
  if (loaded.key === key) return loaded
  const size = partBytes(ui)
  let text = readEntry(book.path, book.spine[s], p * size, size) || ''
  // Whether the chapter goes on past this part: only a part read whole can.
  const more = text.length * 3 >= size - 8 && utf8Length(text) >= size - 8
  // A tag cut at either end of a part is left out.
  if (p > 0) {
    const close = text.indexOf('>')
    const open = text.indexOf('<')
    if (close >= 0 && (open < 0 || close < open)) text = text.slice(close + 1)
  }
  if (more) {
    const open = text.lastIndexOf('<')
    if (open >= 0 && text.indexOf('>', open) < 0) text = text.slice(0, open)
  }
  // Pictures the book does not hold, or the frame cannot read, are left out;
  // one alone on its page (a cover, a plate) fills the page.
  const blocks = parseChapter(text, dirOf(book.spine[s])).filter((block) => block.k !== 'img' || pictureSize(book.path, block.src))
  if (blocks.length === 1 && blocks[0].k === 'img') blocks[0].alone = true
  let chars = 0
  for (const block of blocks) chars += block.t.length + 1
  loaded = { key, blocks, more, chars }
  return loaded
}

// ---- Pictures ------------------------------------------------------------------

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const B64_INDEX = {}
for (let i = 0; i < 64; i++) B64_INDEX[B64[i]] = i

function bytesOf(base64) {
  const clean = base64.replace(/[^A-Za-z0-9+/]/g, '')
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let o = 0
  for (let i = 0; i + 1 < clean.length; i += 4) {
    const n =
      (B64_INDEX[clean[i]] << 18) | (B64_INDEX[clean[i + 1]] << 12) | ((B64_INDEX[clean[i + 2]] || 0) << 6) | (B64_INDEX[clean[i + 3]] || 0)
    out[o++] = (n >> 16) & 255
    if (i + 2 < clean.length) out[o++] = (n >> 8) & 255
    if (i + 3 < clean.length) out[o++] = n & 255
  }
  return out.subarray(0, o)
}

// A picture's width and height off its header, without decoding it: what a
// page needs to know to lay it out. null when it is no picture the frame reads.
const pictureSizes = new Map() // book path | member -> [w, h] | null

function pictureSize(path, src) {
  const key = `${path}|${src}`
  if (pictureSizes.has(key)) return pictureSizes.get(key)
  let size = null
  const at = placeOf(path)
  const head = (length) => bytesOf(frameos.readAsset(at.path, { entry: src, length, storage: at.storage }) || '')
  try {
    let b = head(64)
    const be16 = (i) => (b[i] << 8) | b[i + 1]
    const be32 = (i) => ((b[i] << 24) >>> 0) + (b[i + 1] << 16) + (b[i + 2] << 8) + b[i + 3]
    const le16 = (i) => b[i] | (b[i + 1] << 8)
    const le24 = (i) => b[i] | (b[i + 1] << 8) | (b[i + 2] << 16)
    if (b.length >= 24 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) {
      size = [be32(16), be32(20)]
    } else if (b.length >= 10 && b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46) {
      size = [le16(6), le16(8)]
    } else if (b.length >= 26 && b[0] === 0x42 && b[1] === 0x4d) {
      size = [Math.abs(le24(18) | (b[21] << 24)), Math.abs(le24(22) | (b[25] << 24))]
    } else if (b.length >= 30 && b[0] === 0x52 && b[8] === 0x57 && b[9] === 0x45) {
      const kind = String.fromCharCode(b[12], b[13], b[14], b[15])
      if (kind === 'VP8X') size = [1 + le24(24), 1 + le24(27)]
      else if (kind === 'VP8 ') size = [le16(26) & 0x3fff, le16(28) & 0x3fff]
      else if (kind === 'VP8L') size = [1 + (((b[22] & 0x3f) << 8) | b[21]), 1 + (((b[24] & 0xf) << 10) | (b[23] << 2) | ((b[22] & 0xc0) >> 6))]
    } else if (b.length >= 4 && b[0] === 0xff && b[1] === 0xd8) {
      // A JPEG says its size in its frame header, after whatever comes first
      // (EXIF, a thumbnail): its markers walked, in the first 64 KB.
      b = head(64 * 1024)
      let i = 2
      while (i + 9 < b.length) {
        if (b[i] !== 0xff) {
          i++
          continue
        }
        const marker = b[i + 1]
        if (marker === 0xff) {
          i++
          continue
        }
        if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
          i += 2
          continue
        }
        if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
          size = [be16(i + 7), be16(i + 5)]
          break
        }
        i += 2 + be16(i + 2)
      }
    }
  } catch (e) {
    size = null
  }
  if (size && !(size[0] > 0 && size[1] > 0)) size = null
  pictureSizes.set(key, size)
  return size
}

// Decoded pictures kept between renders, at the size they are drawn. Only
// what the page shows is kept: the frame holds 8 big ones at most.
let pictures = new Map() // key -> image ref

function picturesFor(wanted, background) {
  const next = new Map()
  for (const [key, ref] of pictures) {
    if (wanted.some((want) => want.key === key)) next.set(key, ref)
    else frameos.releaseImage(ref)
  }
  for (const want of wanted) {
    if (next.has(want.key)) continue
    const at = placeOf(want.path)
    const ref = frameos.loadAssetImage(at.path, {
      entry: want.src,
      width: want.w,
      height: want.h,
      fit: want.fit || 'contain',
      keep: true,
      background,
      storage: at.storage,
    })
    next.set(want.key, ref || null)
  }
  pictures = next
  return pictures
}

// ---- Pages ---------------------------------------------------------------------

function geometry(ui, size, book) {
  const fs = Math.round(SIZES[size] * zoom)
  const lh = Math.round(fs * 1.42)
  const margin = Math.round(Math.max(18, Math.min(56, ui.width / zoom / 22)) * zoom)
  const bar = Math.round(34 * zoom)
  // Two columns when one would run past about 80 characters a line (an
  // average character is half an em), so each still holds 40.
  const cols = (ui.width - margin * 2) / (fs * 0.5) > 80 ? 2 : 1
  const gap = Math.round(56 * zoom)
  const w = Math.floor((ui.width - margin * 2 - gap * (cols - 1)) / cols)
  const room = ui.height - bar * 2 - Math.round(12 * zoom)
  // Whole lines of body text: the page's room rounded down to them.
  const h = Math.max(lh, Math.floor(room / lh) * lh)
  const sizeOf = (src) => pictureSize(book.path, src)
  return { fs, lh, margin, bar, cols, gap, w, h, top: bar + Math.round((room - h) / 2) + Math.round(6 * zoom), sizeOf }
}

// Where the line that starts at `from` ends: after the last space (or dash)
// that fits, or inside a word longer than the line.
function breakLine(text, from, width, unit) {
  let sum = 0
  let space = -1
  const limit = width * 0.985
  for (let i = from; i < text.length; i++) {
    const code = text.charCodeAt(i)
    if (code === 32) space = i
    sum += widthOf(code) * unit
    if (sum > limit) {
      if (space > from) return space
      return Math.max(from + 1, i)
    }
    if ((code === 45 || code === 0x2014 || code === 0x2013) && i > from) space = i + 1
  }
  return text.length
}

// One page from `start` ([block, char]): its lines, and where the next page
// starts (null at the end of the chapter's part).
function layoutPage(blocks, start, g) {
  const lines = []
  let y = 0
  let b = start[0]
  let c = start[1]
  while (b < blocks.length) {
    const block = blocks[b]
    const style = STYLES[block.k] || STYLES.p
    const fs = Math.round(g.fs * style.scale)
    const lh = Math.round(g.lh * style.scale)
    // A line after a <br/> (verse, an address) goes on the block before it:
    // no room between the two.
    // A heading under a heading (a chapter's title under its number) sits
    // close to it.
    const prior = b > 0 ? blocks[b - 1] : null
    const stacked = isHeading(block) && prior && isHeading(prior)
    const before = c === 0 && lines.length > 0 && !block.ni ? Math.round((stacked ? 0.15 : style.before) * g.lh) : 0
    const left = Math.round(style.left * g.fs)
    if (block.k === 'img') {
      // As wide as the picture is (in the UI's pixels), at most the column
      // and the page; on the next page when it does not fit under the text.
      const size = g.sizeOf(block.src)
      if (size) {
        let w = block.alone ? g.w : Math.min(g.w, Math.round(size[0] * zoom))
        let h = Math.round((w * size[1]) / size[0])
        if (h > g.h) {
          h = g.h
          w = Math.max(1, Math.round((h * size[0]) / size[1]))
        }
        const gap = Math.round(0.4 * g.lh)
        const top = lines.length > 0 ? y + gap : y
        if (lines.length > 0 && top + h > g.h) return { lines, next: [b, 0] }
        if (w >= 4 && h >= 4) {
          lines.push({ img: block.src, alt: block.alt, x: Math.round((g.w - w) / 2), y: top, w, h })
          y = top + h + gap
        }
      }
      b++
      c = 0
      continue
    }
    if (block.k === 'hr') {
      if (lines.length > 0 && y + before + lh > g.h) return { lines, next: [b, 0] }
      lines.push({ hr: true, y: y + before, lh })
      y += before + lh + Math.round(style.after * g.lh)
      b++
      c = 0
      continue
    }
    const prev = b > 0 ? blocks[b - 1] : null
    const indent = block.k === 'p' && !block.ni && prev && prev.k === 'p' ? Math.round(g.fs * 1.4) : 0
    const unit = (fs / 100) * (style.bold ? 1.07 : 1)
    let first = true
    while (c < block.t.length) {
      const top = y + (first ? before : 0)
      if (lines.length > 0 && top + lh > g.h) return { lines, next: [b, c] }
      const inset = left + (c === 0 ? indent : 0)
      const end = breakLine(block.t, c, g.w - inset, unit)
      lines.push({ t: block.t.slice(c, end).trim(), x: inset, y: top, fs, lh, bold: style.bold })
      y = top + lh
      first = false
      c = end
      while (block.t.charCodeAt(c) === 32) c++
    }
    const following = blocks[b + 1]
    if (!(following && (following.ni || (isHeading(block) && isHeading(following))))) y += Math.round(style.after * g.lh)
    b++
    c = 0
  }
  return { lines, next: null }
}

const isHeading = (block) => block.k === 'h' || block.k === 'h3'

const before = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1])

// ---- Moving through the book ---------------------------------------------------

// The pages of the chapter part `at` is in, as far as they are known, and
// which spread shows: kept in the spot, so a page back costs nothing.
function pagesFor(spot, book, at, g, ui) {
  const chapter = chapterOf(book, at.s, at.p, ui)
  const key = `${book.path}|${at.s}|${at.p}|${g.fs}|${g.lh}|${g.w}|${g.h}|${g.cols}`
  let pg = spot.pg
  if (!pg || pg.key !== key || !Array.isArray(pg.starts)) {
    pg = { key, starts: [[0, 0]], i: 0 }
    const target = [at.b || 0, at.c || 0]
    for (let guard = 0; guard < 5000; guard++) {
      const next = layoutPage(chapter.blocks, pg.starts[pg.starts.length - 1], g).next
      if (!next || before(target, next)) break
      pg.starts.push(next)
    }
    pg.i = pg.starts.length - 1
    pg.i -= pg.i % g.cols
  }
  spot.pg = pg
  return { chapter, pg }
}

// Every page of a part, for a turn back into it from the chapter after.
function lastSpread(spot, book, at, g, ui) {
  spot.pg = null
  const { chapter, pg } = pagesFor(spot, book, { s: at.s, p: at.p, b: 1e9, c: 0 }, g, ui)
  return { chapter, pg }
}

const hasText = (book, s, p, ui) => chapterOf(book, s, p, ui).blocks.length > 0

// The next part with text after (s, p), or null at the end of the book.
function nextPart(book, s, p, ui) {
  let at = { s, p }
  for (let guard = 0; guard < 400; guard++) {
    const chapter = chapterOf(book, at.s, at.p, ui)
    at = chapter.more ? { s: at.s, p: at.p + 1 } : { s: at.s + 1, p: 0 }
    if (at.s >= book.spine.length) return null
    if (hasText(book, at.s, at.p, ui)) return at
  }
  return null
}

function prevPart(book, s, p, ui) {
  let at = { s, p }
  for (let guard = 0; guard < 400; guard++) {
    if (at.p > 0) at = { s: at.s, p: at.p - 1 }
    else {
      if (at.s === 0) return null
      // The chapter before, at its last part.
      let q = 0
      while (q < 50 && chapterOf(book, at.s - 1, q, ui).more) q++
      at = { s: at.s - 1, p: q }
    }
    if (hasText(book, at.s, at.p, ui)) return at
  }
  return null
}

function turn(spot, book, by, g, ui) {
  const at = spot.at
  let { chapter, pg } = pagesFor(spot, book, at, g, ui)
  if (by > 0) {
    // The pages of the spread after this one, laid out once and kept.
    let ok = true
    for (let k = 0; k < g.cols; k++) {
      const i = pg.i + k
      if (pg.starts.length > i + 1) continue
      const next = layoutPage(chapter.blocks, pg.starts[i], g).next
      if (!next) {
        ok = false
        break
      }
      pg.starts.push(next)
    }
    if (ok && pg.starts.length > pg.i + g.cols) {
      pg.i += g.cols
    } else {
      const part = nextPart(book, at.s, at.p, ui)
      if (!part) return false
      spot.pg = null
      Object.assign(at, part, { b: 0, c: 0 })
      return true
    }
  } else if (pg.i - g.cols >= 0) {
    pg.i -= g.cols
  } else {
    const part = prevPart(book, at.s, at.p, ui)
    if (!part) return false
    Object.assign(at, part)
    pg = lastSpread(spot, book, at, g, ui).pg
  }
  const start = pg.starts[pg.i]
  at.b = start[0]
  at.c = start[1]
  return true
}

// ---- The library ---------------------------------------------------------------

// Every .epub below the folder, in every storage the frame has, as keys.
function booksIn(folder, storages, fresh) {
  const where = `${folder}|${storages.map((s) => s.id).join(',')}`
  const kept = fresh ? null : frameos.recall('library')
  if (!fresh && listed.folder === where && Date.now() - listed.at < LIST_MS) return listed.books
  if (kept && typeof kept === 'object' && kept.folder === where && Date.now() - kept.at < LIST_MS && Array.isArray(kept.books)) {
    listed = kept
    return listed.books
  }
  const books = []
  for (const storage of storages) {
    for (const path of frameos.listAssets(folder, { storage: storage.id }) || []) {
      if (/\.epub$/i.test(path) && !/(^|\/)\._/.test(path)) books.push(keyOf(storage.id, path))
    }
  }
  listed = { folder: where, at: Date.now(), books }
  frameos.remember('library', listed)
  return books
}

// A book's title, author and cover, read from its package once and kept in
// the spot (`shelf`): on an ESP32's flash a package costs seconds to read, and
// a frame that sleeps would read every one again at each wake. Refresh
// forgets them.
function metaOf(path, spot) {
  if (metas.has(path)) return metas.get(path)
  const shelf = spot.shelf && typeof spot.shelf === 'object' ? spot.shelf : (spot.shelf = {})
  let meta = shelf[path]
  if (!meta || typeof meta !== 'object' || typeof meta.title !== 'string') {
    const pkg = readPackage(path)
    meta = pkg.error ? { title: bookName(path), author: '', error: pkg.error } : { title: pkg.title, author: pkg.author, cover: pkg.cover || null }
    shelf[path] = meta
  }
  metas.set(path, meta)
  return meta
}

// ---- Looks -------------------------------------------------------------------------

function uiOf(app, context) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const fast = app.frame.fast ?? !paper
  const theme = app.frame.theme && typeof app.frame.theme === 'object' ? app.frame.theme : null
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  const shortSide = Math.min(width, height) * (app.frame.scale || 1)
  zoom = Math.max(0.75, Math.min(2.25, Math.round((shortSide / 480) * 4) / 4))
  return {
    paper,
    slow: !fast,
    themed: !!theme,
    width,
    height,
    embedded: app.frame.embedded === true,
    // The page itself is paper-coloured everywhere: black on white on
    // e-paper, a warm white on a screen.
    sheet: ink ? 'bg-white text-black' : 'bg-[#fbf8f1] text-[#1d1b18]',
    // Under a picture's transparent parts (a line drawing on nothing).
    paperColor: ink ? '#ffffff' : '#fbf8f1',
    rule: ink ? '#000000' : '#c9c2b4',
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    sheetMuted: ink ? 'text-black' : 'text-[#7a7368]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    sheetSoft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#efe9dd] text-[#1d1b18]',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    press: !fast ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    line: ink ? 'border-b-2 border-black' : 'border-b border-[#1f2635]',
    bar: ink ? '#000000' : '#3b82f6',
  }
}

const Chevron = ({ size, left }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" d={left ? 'M15 5L8 12L15 19' : 'M9 5L16 12L9 19'} />
  </svg>
)

const BookGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" d="M4 4.5A1.5 1.5 0 0 1 5.5 3H19v15H5.5A1.5 1.5 0 0 0 4 19.5Z M4 19.5A1.5 1.5 0 0 0 5.5 21H19v-3" />
  </svg>
)

const ListGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="currentColor" d="M4 5h3v3H4ZM9 5.5h11v2H9ZM4 10.5h3v3H4ZM9 11h11v2H9ZM4 16h3v3H4ZM9 16.5h11v2H9Z" />
  </svg>
)

const Refresh = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" d="M19 12a7 7 0 1 1-2.05-4.95M19 4v4h-4" />
  </svg>
)

// ---- Views ---------------------------------------------------------------------------

function Reader({ ui, spot, book, g, save }) {
  const { chapter, pg } = pagesFor(spot, book, spot.at, g, ui)
  const pages = []
  for (let k = 0; k < g.cols; k++) {
    const start = pg.starts[pg.i + k] || (k > 0 && pages[k - 1].next) || null
    pages.push(start ? layoutPage(chapter.blocks, start, g) : { lines: [], next: null })
  }
  // The pictures on the spread, decoded at the size they are drawn.
  const pictureKey = (line) => `${book.path}|${line.img}|${line.w}x${line.h}`
  const wanted = []
  for (const page of pages)
    for (const line of page.lines) if (line.img) wanted.push({ key: pictureKey(line), path: book.path, src: line.img, w: line.w, h: line.h })
  const shown = picturesFor(wanted, ui.paperColor)
  const at = spot.at
  // How far through: the chapter by its text, the book by its chapters.
  let done = 0
  for (let b = 0; b < at.b && b < chapter.blocks.length; b++) done += chapter.blocks[b].t.length + 1
  const inPart = chapter.chars > 0 ? Math.min(1, (done + at.c) / chapter.chars) : 0
  const share = Math.min(1, (at.s + (chapter.more || at.p > 0 ? 0.5 : inPart)) / book.spine.length)
  const end = !pages[pages.length - 1].next && !chapter.more && at.s >= book.spine.length - 1
  const percent = end ? 100 : Math.floor(share * 100)
  let label = ''
  for (const entry of book.toc || []) if (entry.s <= at.s) label = entry.label
  const go = (by) => {
    spot.cmd = by > 0 ? 'next' : 'prev'
    spot.keys = false
    save(spot)
  }
  const tool = `flex items-center justify-center h-[${px(30)}] min-w-[${px(34)}] px-[${px(8)}] rounded-[${px(8)}] text-[${px(14)}] shrink-0 ${ui.sheetSoft} ${ui.press}`
  const progress = Math.round((ui.width * percent) / 100)
  return (
    <div className={`relative w-full h-full ${ui.sheet}`}>
      {pages.map((page, k) =>
        page.lines.map((line) => {
          const left = g.margin + k * (g.w + g.gap) + line.x
          if (line.img) {
            const ref = shown.get(pictureKey(line))
            return ref ? (
              <img className={`absolute left-[${raw(left)}] top-[${raw(g.top + line.y)}] w-[${raw(line.w)}] h-[${raw(line.h)}]`} src={ref} />
            ) : (
              <div
                className={`absolute left-[${raw(left)}] top-[${raw(g.top + line.y)}] w-[${raw(line.w)}] h-[${raw(line.h)}] flex items-center justify-center p-[${px(8)}] border border-[${ui.rule}] text-center text-[${px(14)}] ${ui.sheetMuted}`}
              >
                {line.alt || 'A picture'}
              </div>
            )
          }
          return line.hr ? (
            <svg
              className={`absolute left-[${raw(g.margin + k * (g.w + g.gap))}] top-[${raw(g.top + line.y)}]`}
              width={g.w}
              height={line.lh}
              viewBox={`0 0 ${g.w} ${line.lh}`}
            >
              <path fill="none" stroke={ui.rule} strokeWidth={Math.max(1, Math.round(zoom))} d={`M${Math.round(g.w * 0.35)} ${Math.round(line.lh / 2)}H${Math.round(g.w * 0.65)}`} />
            </svg>
          ) : (
            <div
              className={`absolute left-[${raw(g.margin + k * (g.w + g.gap) + line.x)}] top-[${raw(g.top + line.y)}] h-[${raw(line.lh)}] leading-[${raw(line.lh)}] text-[${raw(line.fs)}] whitespace-nowrap ${line.bold ? 'font-bold' : ''}`}
            >
              {line.t}
            </div>
          )
        })
      )}
      {end ? (
        <div className={`absolute right-[${raw(g.margin)}] bottom-[${raw(g.bar)}] text-[${px(14)}] ${ui.sheetMuted}`}>The end</div>
      ) : null}
      <div
        className={`absolute left-0 right-0 top-[${raw(g.bar)}] bottom-[${raw(g.bar)}] flex`}
        onSwipe={(e) => {
          if (e.direction === 'left' || e.direction === 'up') go(1)
          else if (e.direction === 'right' || e.direction === 'down') go(-1)
        }}
      >
        <div className="w-1/3 h-full" onClick={() => go(-1)} />
        <div className="flex-1 h-full" onClick={() => go(1)} />
      </div>
      <div className={`absolute left-0 right-0 top-0 flex items-center gap-[${px(8)}] h-[${raw(g.bar)}] px-[${raw(Math.max(4, g.margin - 8 * zoom))}]`}>
        <div look="button" className={tool} onClick={() => go_(spot, save, { view: 'library' })}>
          <BookGlyph size={18} />
        </div>
        <span className={`flex-1 min-w-0 truncate text-[${px(14)}] ${ui.sheetMuted}`}>
          {[book.title, label && label !== book.title ? label : ''].filter(Boolean).join(' · ')}
        </span>
        <div look="button" className={tool} onClick={() => go_(spot, save, { size: Math.max(0, spot.size - 1) })}>
          A−
        </div>
        <div look="button" className={tool} onClick={() => go_(spot, save, { size: Math.min(SIZES.length - 1, spot.size + 1) })}>
          A+
        </div>
        {book.toc && book.toc.length > 0 ? (
          <div look="button" className={tool} onClick={() => go_(spot, save, { view: 'contents', tocPage: null, sel: -1 })}>
            <ListGlyph size={18} />
          </div>
        ) : null}
      </div>
      <div className={`absolute left-0 right-0 bottom-0 flex items-center justify-between h-[${raw(g.bar)}] px-[${raw(g.margin)}] text-[${px(13)}] ${ui.sheetMuted}`}>
        <span className="whitespace-nowrap">{`Chapter ${at.s + 1} of ${book.spine.length}`}</span>
        <span className="whitespace-nowrap">{`${percent}%`}</span>
      </div>
      {progress > 0 ? <div className={`absolute left-0 bottom-0 w-[${raw(progress)}] h-[${raw(Math.max(2, 3 * zoom))}] bg-[${ui.rule}]`} /> : null}
    </div>
  )
}

function go_(spot, save, change) {
  Object.assign(spot, change)
  spot.keys = false
  save(spot)
}

// Rows into pages that fit `room` (the UI's pixels), each row its `height`:
// a heading never ends a page.
function paginate(rows, room) {
  const pages = [[]]
  let used = 0
  rows.forEach((row, i) => {
    const next = rows[i + 1]
    const need = row.header && next ? row.height + next.height : row.height
    if (used + need > room && pages[pages.length - 1].length > 0) {
      pages.push([])
      used = 0
    }
    pages[pages.length - 1].push(row)
    used += row.height
  })
  return pages
}

const pageOf = (pages, index) => Math.max(0, pages.findIndex((page) => page.some((row) => row.index === index)))
const listRoom = (ui) => ui.height / zoom - 56 - 46

// A paged list (the library, the contents): rows, headings among them, arrows,
// and a highlight the keys move. A row's `index` is what onOpen gets.
function Listing({ ui, title, pages: pageRows, page, sel, keys, onPage, onOpen, actions, empty }) {
  const pages = Math.max(1, pageRows.length)
  const shown = pageRows[page] || []
  const rows = pageRows.flat()
  const arrow = `flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${ui.soft} ${ui.press}`
  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(10)}] h-[${px(56)}] px-[${px(16)}] shrink-0`}>
        {title}
        {actions}
      </div>
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-hidden px-[${px(16)}]`}
        onSwipe={(e) => {
          if (e.direction === 'left' || e.direction === 'up') onPage(1)
          else if (e.direction === 'right' || e.direction === 'down') onPage(-1)
        }}
      >
        {rows.length === 0 ? (
          <div look="muted" className={`flex flex-col items-center justify-center flex-1 gap-[${px(10)}] px-[${px(24)}] ${ui.muted}`}>
            <BookGlyph size={48} />
            <span className={`text-[${px(16)}] text-center`}>{empty}</span>
          </div>
        ) : (
          shown.map((row) => {
            if (row.header) {
              return (
                <div look="muted" className={`flex items-end h-[${px(row.height)}] px-[${px(10)}] pb-[${px(5)}] shrink-0 text-[${px(13)}] font-bold ${ui.muted}`}>
                  {row.label}
                </div>
              )
            }
            const lit = keys && row.index === sel
            return (
              <div
                look={lit ? 'selected' : 'option'}
                className={`flex items-center gap-[${px(12)}] h-[${px(row.height)}] px-[${px(10)}] shrink-0 ${ui.line} ${lit ? ui.accent : ui.press}`}
                onClick={() => onOpen(row.index)}
              >
                {row.thumb ? <img className={`w-[${raw(row.thumbW)}] h-[${raw(row.thumbH)}] shrink-0`} src={row.thumb} /> : null}
                <div className={`flex flex-col justify-center gap-[${px(2)}] flex-1 min-w-0`}>
                  <span className={`text-[${px(row.sub ? 17 : 16)}] ${row.bold ? 'font-bold' : ''} truncate`}>{row.label}</span>
                  {row.sub ? (
                    <span look="muted" className={`text-[${px(13)}] ${lit ? '' : ui.muted} truncate`}>
                      {row.sub}
                    </span>
                  ) : null}
                </div>
              </div>
            )
          })
        )}
      </div>
      <div className={`flex items-center justify-end gap-[${px(6)}] h-[${px(46)}] px-[${px(16)}] shrink-0`}>
        {pages > 1
          ? [
              page > 0 ? (
                <div look="button" className={arrow} onClick={() => onPage(-1)}>
                  <Chevron size={18} left />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
              <span look="muted" className={`w-[${px(72)}] text-center text-[${px(13)}] ${ui.muted}`}>{`${page + 1} of ${pages}`}</span>,
              page < pages - 1 ? (
                <div look="button" className={arrow} onClick={() => onPage(1)}>
                  <Chevron size={18} />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
            ]
          : null}
      </div>
    </div>
  )
}

// Opens a book where it was left, or at its first page with text.
function openAt(spot, path, ui) {
  const book = openBook(path)
  if (book.error) return book
  const kept = spot.books && spot.books[path]
  const at = kept && typeof kept.s === 'number' && kept.s < book.spine.length ? { s: kept.s, p: kept.p || 0, b: kept.b || 0, c: kept.c || 0 } : { s: 0, p: 0, b: 0, c: 0 }
  if (!hasText(book, at.s, at.p, ui)) {
    const next = nextPart(book, at.s, at.p, ui)
    if (next) Object.assign(at, next, { b: 0, c: 0 })
  }
  spot.at = at
  return book
}

// Where a book was left, for the library and the next open; the books read
// longest ago are forgotten first.
function keepPlace(spot, book) {
  const books = spot.books && typeof spot.books === 'object' ? spot.books : {}
  books[book.path] = { s: spot.at.s, p: spot.at.p, b: spot.at.b, c: spot.at.c, n: book.spine.length, t: Date.now(), title: book.title, author: book.author, cover: book.cover || null }
  const paths = Object.keys(books).sort((a, b) => (books[b].t || 0) - (books[a].t || 0))
  for (const path of paths.slice(BOOKS_KEPT)) delete books[path]
  spot.books = books
}

export function onEvent(app, context) {
  const p = context.payload || {}
  const event = context.event
  let cmd = null
  if (event === 'button') {
    if (p.action !== 'press') return false
    const label = String(p.label || '').toUpperCase()
    if (label === 'DOWN' || label === 'RIGHT' || label === 'NEXT') cmd = 'next'
    else if (label === 'UP' || label === 'LEFT' || label === 'PREV' || label === 'PREVIOUS') cmd = 'prev'
    else cmd = 'select'
  } else if (event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    const key = p.key
    if (key === 'ArrowRight' || key === 'ArrowDown' || key === 'PageDown' || key === ' ') cmd = 'next'
    else if (key === 'ArrowLeft' || key === 'ArrowUp' || key === 'PageUp') cmd = 'prev'
    else if (key === 'Enter') cmd = 'select'
    else if (key === 'Escape' || key === 'Backspace') cmd = 'back'
  } else if (event === 'forward') cmd = 'next'
  else if (event === 'back') cmd = 'prev'
  if (!cmd) return false
  const spot = readSpot(app)
  spot.cmd = cmd
  spot.keys = true
  saveSpot(spot)
  return true
}

export function get(app, context) {
  const ui = uiOf(app, context)
  const spot = readSpot(app)
  const save = (next) => saveSpot(next)
  spot.view = spot.view === 'book' || spot.view === 'contents' ? spot.view : 'library'
  spot.size = Number.isInteger(spot.size) && spot.size >= 0 && spot.size < SIZES.length ? spot.size : DEFAULT_SIZE
  let cmd = spot.cmd || null
  delete spot.cmd
  const folder = typeof app.state.folder === 'string' ? app.state.folder.trim().replace(/^\/+|\/+$/g, '') : ''
  const storages = storagesOf(app)
  // Keys from before storages (bare paths) are the assets folder's.
  if (spot.book) spot.book = normalKey(spot.book, storages)
  for (const field of ['books', 'shelf']) {
    const map = spot[field]
    if (map && typeof map === 'object' && Object.keys(map).some((key) => normalKey(key, storages) !== key)) {
      const moved = {}
      for (const key of Object.keys(map)) moved[normalKey(key, storages)] = map[key]
      spot[field] = moved
    }
  }
  const kept = spot.books && typeof spot.books === 'object' ? spot.books : {}

  // A book another scene opened here (the Files app), where it was left.
  const handed = typeof app.state.file === 'string' ? normalKey(app.state.file.trim(), storages) : ''
  if (handed) {
    frameos.setState('file', '')
    const book = openAt(spot, handed, ui)
    if (book.error) {
      spot.view = 'library'
      spot.problem = `${bookName(handed)}: ${book.error}`
    } else {
      spot.book = handed
      spot.view = 'book'
      spot.pg = null
      spot.problem = ''
      keepPlace(spot, book)
    }
  }

  // The library's books, the one read last first.
  let books = null
  const shelf = () => {
    if (books) return books
    const fresh = spot.refresh === true
    delete spot.refresh
    if (fresh) {
      spot.shelf = {}
      metas.clear()
    }
    const order = storages.map((s) => s.id)
    books = booksIn(folder, storages, fresh)
      .slice()
      .sort((a, b) => {
        const sa = order.indexOf(placeOf(a).storage)
        const sb = order.indexOf(placeOf(b).storage)
        const ta = (kept[a] && kept[a].t) || 0
        const tb = (kept[b] && kept[b].t) || 0
        return sa - sb || tb - ta || bookName(a).toLowerCase().localeCompare(bookName(b).toLowerCase())
      })
    return books
  }
  // Opens the library's book i where it was left.
  const open = (i) => {
    const path = shelf()[i]
    if (!path) return
    const book = openAt(spot, path, ui)
    if (book.error) {
      spot.problem = `${bookName(path)}: ${book.error}`
    } else {
      spot.book = path
      spot.view = 'book'
      spot.pg = null
      spot.problem = ''
      spot.sel = i
      keepPlace(spot, book)
    }
  }

  // A key in the library: the highlight, or the book under it.
  if (spot.view === 'library' && cmd) {
    if (cmd === 'select' && shelf().length > 0) {
      open(Math.max(0, Math.min(spot.sel || 0, shelf().length - 1)))
      cmd = null
    } else if (cmd === 'back' && spot.book) {
      spot.view = 'book'
      cmd = null
    }
  }

  // A book open: its contents, or its pages.
  if (spot.view !== 'library' && spot.book) {
    const book = openBook(spot.book)
    if (book.error) {
      spot.view = 'library'
      spot.problem = `${bookName(spot.book)}: ${book.error}`
    } else {
      if (!spot.at || typeof spot.at.s !== 'number' || spot.at.s >= book.spine.length) openAt(spot, spot.book, ui)
      const g = geometry(ui, spot.size, book)
      const toc = book.toc || []
      let current = 0
      toc.forEach((entry, i) => {
        if (entry.s <= spot.at.s) current = i
      })
      const jump = (i) => {
        const entry = toc[i]
        if (!entry) return
        spot.at = { s: entry.s, p: 0, b: 0, c: 0 }
        spot.pg = null
        spot.view = 'book'
        spot.keys = false
        keepPlace(spot, book)
        save(spot)
      }
      if (spot.view === 'contents' && cmd) {
        if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = current
        if (cmd === 'next') spot.sel = Math.min(toc.length - 1, spot.sel + 1)
        else if (cmd === 'prev') spot.sel = Math.max(0, spot.sel - 1)
        else if (cmd === 'select') {
          jump(spot.sel)
          cmd = null
        } else if (cmd === 'back') {
          spot.view = 'book'
          cmd = null
        }
      } else if (spot.view === 'book' && cmd) {
        if (cmd === 'next' || cmd === 'prev') turn(spot, book, cmd === 'next' ? 1 : -1, g, ui)
        else {
          spot.view = 'library'
          spot.sel = Math.max(0, shelf().indexOf(spot.book))
          spot.page = null
        }
        cmd = null
      }
      if (spot.view === 'book') {
        // The pages first: what they add to the spot is saved with it.
        pagesFor(spot, book, spot.at, g, ui)
        keepPlace(spot, book)
        save(spot)
        return <Reader ui={ui} spot={spot} book={book} g={g} save={save} />
      }
      if (spot.view === 'contents') {
        if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = current
        spot.sel = Math.max(0, Math.min(spot.sel, toc.length - 1))
        const pages = paginate(
          toc.map((entry, i) => ({ label: entry.label, bold: i === current, index: i, height: 46 })),
          listRoom(ui)
        )
        if (typeof spot.tocPage !== 'number' || cmd) spot.tocPage = pageOf(pages, spot.sel)
        spot.tocPage = Math.max(0, Math.min(spot.tocPage, pages.length - 1))
        save(spot)
        const button = `flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`
        return (
          <Listing
            ui={ui}
            title={[
              <div look="button" className={button} onClick={() => go_(spot, save, { view: 'book' })}>
                <Chevron size={20} left />
              </div>,
              <div className="flex flex-col flex-1 min-w-0">
                <span className={`text-[${px(19)}] font-bold truncate`}>Contents</span>
                <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
                  {book.title}
                </span>
              </div>,
            ]}
            pages={pages}
            page={spot.tocPage}
            sel={spot.sel}
            keys={spot.keys === true}
            onPage={(by) => go_(spot, save, { tocPage: spot.tocPage + by })}
            onOpen={jump}
            empty="This book has no contents."
          />
        )
      }
    }
  }

  // The library: the books of each storage under its name, when there are two.
  spot.view = 'library'
  const list = shelf()
  if (typeof spot.sel !== 'number' || spot.sel < 0) spot.sel = 0
  spot.sel = Math.min(spot.sel, Math.max(0, list.length - 1))
  if (cmd === 'next') spot.sel = Math.min(Math.max(0, list.length - 1), spot.sel + 1)
  else if (cmd === 'prev') spot.sel = Math.max(0, spot.sel - 1)
  const rows = []
  list.forEach((key, i) => {
    const storage = placeOf(key).storage
    if (storages.length > 1 && (i === 0 || placeOf(list[i - 1]).storage !== storage)) {
      const named = storages.find((s) => s.id === storage)
      rows.push({ header: true, label: named ? named.name : storage, index: -1, height: 34 })
    }
    rows.push({ key, index: i, height: 60 })
  })
  const pages = paginate(rows, listRoom(ui))
  if (typeof spot.page !== 'number' || cmd) spot.page = pageOf(pages, spot.sel)
  spot.page = Math.max(0, Math.min(spot.page, pages.length - 1))
  // What the shelf keeps of books no longer listed goes.
  if (spot.shelf && typeof spot.shelf === 'object') {
    for (const key of Object.keys(spot.shelf)) if (!list.includes(key)) delete spot.shelf[key]
  }

  // Titles and covers for the page showing (the shelf keeps them), the
  // covers small, decoded once while the app lives.
  const thumbW = Math.round(40 * zoom)
  const thumbH = Math.round(52 * zoom)
  const showing = new Set((pages[spot.page] || []).filter((row) => !row.header).map((row) => row.key))
  const metaFor = (key) => {
    const place = kept[key]
    return place && place.title && 'cover' in place
      ? { title: place.title, author: place.author, cover: place.cover }
      : showing.has(key)
        ? metaOf(key, spot)
        : { title: bookName(key), author: '' }
  }
  for (const row of rows) if (!row.header) row.meta = metaFor(row.key)
  // Saved after the shelf took what was read for this page.
  save(spot)
  const coverKey = (key, cover) => `${key}|${cover}|${thumbW}x${thumbH}`
  const covers = picturesFor(
    rows
      .filter((row) => !row.header && row.meta.cover && showing.has(row.key))
      .map((row) => ({ key: coverKey(row.key, row.meta.cover), path: row.key, src: row.meta.cover, w: thumbW, h: thumbH, fit: 'cover' })),
    ui.paperColor
  )
  for (const row of rows) {
    if (row.header) continue
    const place = kept[row.key]
    const progress = place && place.n ? `Chapter ${place.s + 1} of ${place.n}` : row.meta.error ? row.meta.error : 'Not started'
    row.label = row.meta.title
    row.sub = [row.meta.author, progress].filter(Boolean).join(' · ')
    row.bold = row.key === spot.book
    row.thumb = row.meta.cover ? covers.get(coverKey(row.key, row.meta.cover)) || null : null
    row.thumbW = thumbW
    row.thumbH = thumbH
  }
  const button = `flex items-center justify-center gap-[${px(6)}] h-[${px(40)}] px-[${px(12)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`
  const wide = ui.width / zoom >= 560
  // Where books go, in the frame's own words for its storages.
  const names = storages.map((s) => (s.id === 'assets' && s.name === 'TF card' ? 'the TF card' : s.name.toLowerCase().replace(/^internal/, 'the internal')))
  const where = `${folder ? `the folder "${folder}" on ` : ''}${names.join(' or ')}`
  return (
    <Listing
      ui={ui}
      title={[
        <div look="accent" className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.accent}`}>
          <BookGlyph size={22} />
        </div>,
        <div className="flex flex-col flex-1 min-w-0">
          <span className={`text-[${px(20)}] font-bold truncate`}>Books</span>
          {spot.problem ? (
            <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
              {spot.problem}
            </span>
          ) : wide && list.length > 0 ? (
            <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
              {`${list.length} book${list.length === 1 ? '' : 's'}`}
            </span>
          ) : null}
        </div>,
      ]}
      actions={[
        spot.book && kept[spot.book] ? (
          <div look="primary" className={`${button} ${ui.accent}`} onClick={() => go_(spot, save, { view: 'book' })}>
            <span className={`text-[${px(14)}] font-bold`}>{wide ? 'Continue reading' : 'Continue'}</span>
          </div>
        ) : null,
        <div look="button" className={button} onClick={() => go_(spot, save, { refresh: true, problem: '' })}>
          <Refresh size={20} />
        </div>,
      ]}
      pages={pages}
      page={spot.page}
      sel={spot.sel}
      keys={spot.keys === true}
      onPage={(by) => go_(spot, save, { page: spot.page + by })}
      onOpen={(i) => {
        open(i)
        spot.keys = false
        save(spot)
      }}
      empty={`No books yet. Put .epub files on ${where} and they show up here.`}
    />
  )
}
